+import { z } from 'zod';
+import { CARRIERS, SERVICE_LEVELS, type Carrier, type ServiceLevel } from '../types.ts';
+import { checkAtpTrackingNumber } from './trackingNumber.ts';
+
+// Shareable with the mobile team: this file only depends on zod and the plain constants/helpers above.
+
+const requiredString = (label: string) =>
+  z.string({ error: `${label} is required` }).trim().min(1, `${label} is required`);
+
+const optionalTrimmed = z.preprocess(
+  (v) => (typeof v === 'string' && v.trim() === '' ? undefined : v),
+  z.string().trim().optional().catch(undefined),
+);
+
+const recipientSchema = z.object(
+  {
+    name: requiredString('recipient.name'),
+    street: requiredString('recipient.street'),
+    zip: requiredString('recipient.zip'),
+    city: requiredString('recipient.city'),
+    country: z.preprocess(
+      (v) => (typeof v === 'string' && v.trim() !== '' ? v.trim().toUpperCase() : 'AT'),
+      z.string(),
+    ),
+    phone: optionalTrimmed,
+  },
+  { error: 'recipient is required' },
+);
+
+export const shipmentBodySchema = z
+  .object(
+    {
+      tracking_number: requiredString('tracking_number').transform((s) => s.toUpperCase()),
+      carrier: requiredString('carrier')
+        .transform((s) => s.toUpperCase())
+        .pipe(
+          z.custom<Carrier>((v) => CARRIERS.includes(v as Carrier), {
+            error: `carrier must be one of ${CARRIERS.join(', ')}`,
+          }),
+        ),
+      service_level: z
+        .custom<ServiceLevel>((v) => typeof v === 'string' && SERVICE_LEVELS.includes(v as ServiceLevel), {
+          error: `service_level must be one of ${SERVICE_LEVELS.join(', ')}`,
+        })
+        .default('standard'),
+      recipient: recipientSchema,
+    },
+    { error: 'body must be a JSON object' },
+  )
+  .superRefine((body, ctx) => {
+    // Only ATP numbers are validated; other carriers' formats change too often (see docs/carriers.md).
+    if (body.carrier !== 'ATP') return;
+    const check = checkAtpTrackingNumber(body.tracking_number);
+    if (check === 'bad_format') {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['tracking_number'],
+        message: 'Ungültige Sendungsnummer für ATP: erwartet werden 2 Buchstaben, 8 Ziffern, 1 Prüfziffer und AT (z. B. RR123456785AT)',
+      });
+    } else if (check === 'bad_check_digit') {
+      ctx.addIssue({
+        code: 'custom',
+        path: ['tracking_number'],
+        message: 'Ungültige Sendungsnummer für ATP: Die Prüfziffer stimmt nicht',
+      });
+    }
+  });
+
+export type ShipmentBody = z.infer<typeof shipmentBodySchema>;
